# app.services.accounting.DEFAULT_ACCOUNTS의 이 시점 사본(앱 코드가 바뀌어도 마이그레이션은 그대로)
DEFAULT_ACCOUNTS = [
    ("101", "현금", "asset", "cash"),
    ("103", "보통예금", "asset", "bank"),
    ("108", "외상매출금", "asset", "receivable"),
    ("135", "부가세대급금", "asset", "vat_paid"),
    ("146", "상품", "asset", "inventory"),
    ("251", "외상매입금", "liability", "payable"),
    ("255", "부가세예수금", "liability", "vat_received"),
    ("401", "상품매출", "revenue", "sales"),
    ("451", "상품매출원가", "expense", "cogs"),
    ("958", "재고자산감모손실", "expense", "shrinkage_loss"),
    ("959", "재고자산폐기손실", "expense", "disposal_loss"),
]


def _seed_existing() -> None:
    """기존 사업장: 기본 계정과목 추가, 구매·자재 권한을 조정해 둔 사업장은 '재고' 메뉴 추가"""
    conn = op.get_bind()
    business = sa.table("business", sa.column("id"), sa.column("menu_permissions", sa.JSON))
    account = sa.table(
        "account", sa.column("business_id"), sa.column("code"), sa.column("name"),
        sa.column("kind"), sa.column("system_key"), sa.column("is_active"),
    )
    for biz_id, perms in conn.execute(sa.select(business.c.id, business.c.menu_permissions)).all():
        conn.execute(account.insert(), [
            {"business_id": biz_id, "code": code, "name": name, "kind": kind,
             "system_key": key, "is_active": True}
            for code, name, kind, key in DEFAULT_ACCOUNTS
        ])
        if perms:
            changed = {
                role: sorted({*menus, "inventory"}) if "purchase" in menus else menus
                for role, menus in perms.items()
            }
            if changed != perms:
                conn.execute(
                    business.update().where(business.c.id == biz_id).values(menu_permissions=changed)
                )


